'use client';

import {
  eachMonthOfInterval,
  eachYearOfInterval,
  endOfYear,
  format,
  isAfter,
  isBefore,
  startOfYear,
} from 'date-fns';
import { createContext, useContext, useEffect, useRef, useState } from 'react';
import type { CaptionLabelProps, MonthGridProps } from 'react-day-picker';

import { ChevronDownIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/registry/ndeko/ui/collapsible';
import { ScrollArea } from '@/registry/ndeko/ui/scroll-area';

import { AnimatedCalendar } from './_parts/animated-calendar';

const START_MONTH = new Date(1980, 6);
const END_MONTH = new Date(2030, 6);
const YEARS = eachYearOfInterval({
  start: startOfYear(START_MONTH),
  end: endOfYear(END_MONTH),
});
const FOCUS_DELAY_MS = 100;

type YearViewState = {
  isYearView: boolean;
  toggleYearView: () => void;
  currentYear: number;
  currentMonth: number;
  selectMonth: (month: Date) => void;
};

const YearViewContext = createContext<YearViewState | null>(null);

function useYearView() {
  const state = useContext(YearViewContext);
  if (!state) {
    throw new Error('The year view parts must sit inside its provider.');
  }
  return state;
}

function refWhen<T>(isTarget: boolean, ref: React.RefObject<T | null>) {
  if (isTarget) {
    return ref;
  }
  return undefined;
}

function monthVariantOf(isCurrentMonth: boolean) {
  if (isCurrentMonth) {
    return 'default';
  }
  return 'outline';
}

function isOutsideRange(month: Date) {
  const isTooEarly = isBefore(month, START_MONTH);
  const isTooLate = isAfter(month, END_MONTH);
  return isTooEarly || isTooLate;
}

function monthsOf(year: Date) {
  return eachMonthOfInterval({
    start: startOfYear(year),
    end: endOfYear(year),
  });
}

function YearViewCaption({ children }: CaptionLabelProps) {
  const { isYearView, toggleYearView } = useYearView();

  return (
    <Button
      variant='ghost'
      size='sm'
      className='-ms-2 text-[13px] font-medium'
      aria-expanded={isYearView}
      onClick={toggleYearView}
    >
      {children}
      <ChevronDownIcon
        className={cn(
          'text-muted-foreground shrink-0 transition-transform duration-200',
          isYearView && 'rotate-180'
        )}
      />
    </Button>
  );
}

function YearSection({
  title,
  defaultOpen,
  children,
}: {
  title: string;
  defaultOpen: boolean;
  children: React.ReactNode;
}) {
  return (
    <Collapsible
      defaultOpen={defaultOpen}
      className='hairline-t border-border px-2 py-1.5'
    >
      <CollapsibleTrigger
        render={
          <Button
            variant='ghost'
            size='sm'
            className='w-full justify-start text-[13px] font-medium [&[data-panel-open]>svg]:rotate-180'
          />
        }
      >
        <ChevronDownIcon className='text-muted-foreground shrink-0 transition-transform duration-200' />
        {title}
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div className='grid grid-cols-3 gap-2 px-3 py-1'>{children}</div>
      </CollapsibleContent>
    </Collapsible>
  );
}

function YearList() {
  const { currentYear, currentMonth, selectMonth } = useYearView();
  const listRef = useRef<HTMLDivElement>(null);
  const currentYearRef = useRef<HTMLDivElement>(null);
  const currentMonthRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const viewport = listRef.current?.querySelector<HTMLElement>(
      '[data-slot=scroll-area-viewport]'
    );
    const yearElement = currentYearRef.current;
    if (viewport && yearElement) {
      viewport.scrollTop = yearElement.offsetTop;
    }
    const focusTimer = window.setTimeout(() => {
      currentMonthRef.current?.focus();
    }, FOCUS_DELAY_MS);
    return () => window.clearTimeout(focusTimer);
  }, []);

  return (
    <div ref={listRef} className='bg-card absolute inset-0 z-20 -mx-2 -mb-2'>
      <ScrollArea className='h-full'>
        {YEARS.map((year) => {
          const yearNumber = year.getFullYear();
          const isCurrentYear = yearNumber === currentYear;

          return (
            <div key={yearNumber} ref={refWhen(isCurrentYear, currentYearRef)}>
              <YearSection
                title={String(yearNumber)}
                defaultOpen={isCurrentYear}
              >
                {monthsOf(year).map((month) => {
                  const isSameMonthNumber = month.getMonth() === currentMonth;
                  const isCurrentMonth = isSameMonthNumber && isCurrentYear;

                  return (
                    <Button
                      key={month.getTime()}
                      ref={refWhen(isCurrentMonth, currentMonthRef)}
                      variant={monthVariantOf(isCurrentMonth)}
                      size='sm'
                      disabled={isOutsideRange(month)}
                      onClick={() => selectMonth(month)}
                    >
                      {format(month, 'MMM')}
                    </Button>
                  );
                })}
              </YearSection>
            </div>
          );
        })}
      </ScrollArea>
    </div>
  );
}

function YearViewGrid({ children, ...props }: MonthGridProps) {
  const { isYearView } = useYearView();

  return (
    <div className='relative'>
      <table {...props}>{children}</table>
      {isYearView && <YearList />}
    </div>
  );
}

export default function CalendarDatePicker18() {
  const [month, setMonth] = useState(() => new Date());
  const [date, setDate] = useState<Date | undefined>(() => new Date());
  const [isYearView, setIsYearView] = useState(false);

  function toggleYearView() {
    setIsYearView((isOpen) => !isOpen);
  }

  function selectMonth(selectedMonth: Date) {
    setMonth(selectedMonth);
    setIsYearView(false);
  }

  const yearView: YearViewState = {
    isYearView,
    toggleYearView,
    currentYear: month.getFullYear(),
    currentMonth: month.getMonth(),
    selectMonth,
  };

  return (
    <YearViewContext.Provider value={yearView}>
      <AnimatedCalendar
        mode='single'
        selected={date}
        onSelect={setDate}
        month={month}
        onMonthChange={setMonth}
        startMonth={START_MONTH}
        endMonth={END_MONTH}
        className='bg-card hairline-ring ring-border overflow-hidden rounded-xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
        classNames={{
          month_caption: 'ms-2.5 me-20 justify-start',
          nav: 'justify-end',
        }}
        components={{
          CaptionLabel: YearViewCaption,
          MonthGrid: YearViewGrid,
        }}
      />
    </YearViewContext.Provider>
  );
}

'use client';

import { differenceInCalendarDays } from 'date-fns';
import {
  motion,
  useReducedMotion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';
import { useState } from 'react';
import {
  Day,
  useDayPicker,
  type DayProps,
  type MonthProps,
} from 'react-day-picker';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Calendar } from '@/registry/ndeko/ui/calendar';

type CalendarProps = React.ComponentProps<typeof Calendar>;

type ShownMonth = { time: number; direction: number };

const MONTH_SHIFT_PX = 12;
const RANGE_STEP_MS = 12;
const RANGE_GROWTH_MAX_MS = 240;

const MONTH_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const MONTH_AT_REST: TargetAndTransition = { opacity: 1, x: 0 };

const SETTLING_DAY_BUTTON = [
  'transition-[color,background-color,border-radius,box-shadow,scale] ease-(--ease-out-strong) active:scale-90',
  'group-[.range-middle]:[transition-delay:var(--range-delay),var(--range-delay),0ms,0ms,0ms]',
].join(' ');

function rangeStartOf(selected: unknown) {
  if (!selected) {
    return undefined;
  }
  if (typeof selected !== 'object') {
    return undefined;
  }
  if (!('from' in selected)) {
    return undefined;
  }
  return selected.from as Date | undefined;
}

function rangeDelayOf(day: Date, rangeStart: Date | undefined) {
  if (!rangeStart) {
    return '0ms';
  }
  const step = differenceInCalendarDays(day, rangeStart);
  const delay = Math.min(step * RANGE_STEP_MS, RANGE_GROWTH_MAX_MS);
  const positiveDelay = Math.max(0, delay);
  return `${positiveDelay}ms`;
}

function monthEnterOf(direction: number, shouldReduceMotion: boolean | null) {
  if (direction === 0) {
    return false;
  }
  if (shouldReduceMotion) {
    return { opacity: 0 };
  }
  const offset = direction * MONTH_SHIFT_PX;
  return { opacity: 0, x: offset };
}

function GrowingRangeDay({ style, ...props }: DayProps) {
  const { selected } = useDayPicker();
  const rangeStart = rangeStartOf(selected);
  const delay = rangeDelayOf(props.day.date, rangeStart);
  const dayStyle = { ...style, '--range-delay': delay } as React.CSSProperties;

  return <Day {...props} style={dayStyle} />;
}

function SlidingMonth({
  calendarMonth,
  displayIndex,
  children,
  ...props
}: MonthProps) {
  const time = calendarMonth.date.getTime();
  const [shown, setShown] = useState<ShownMonth>({ time, direction: 0 });
  const shouldReduceMotion = useReducedMotion();

  if (shown.time !== time) {
    const direction = Math.sign(time - shown.time);
    setShown({ time, direction });
  }

  return (
    <div data-display-index={displayIndex} {...props}>
      <AnimatedSize>
        <motion.div
          key={time}
          initial={monthEnterOf(shown.direction, shouldReduceMotion)}
          animate={MONTH_AT_REST}
          transition={MONTH_TRANSITION}
        >
          {children}
        </motion.div>
      </AnimatedSize>
    </div>
  );
}

function withSettlingDays(classNames: CalendarProps['classNames']) {
  const dayButton = cn(SETTLING_DAY_BUTTON, classNames?.day_button);
  return { ...classNames, day_button: dayButton };
}

/**
 * The calendar primitive with the date picker micro-interactions: a picked day settles in,
 * a range grows from its start to its end, a new month slides in from the side it comes from
 * and the card resizes to the number of weeks.
 */
function AnimatedCalendar({ classNames, components, ...props }: CalendarProps) {
  return (
    <Calendar
      classNames={withSettlingDays(classNames)}
      components={{ Day: GrowingRangeDay, Month: SlidingMonth, ...components }}
      {...props}
    />
  );
}

export { AnimatedCalendar };
